//! The generated C file.
//!
//! One source file, one entry point: `main` passes the payload to `onde_main_payload` and returns
//! what it returns. Everything else — argv shape, exit codes, error printing — lives in the
//! runtime, so a host embedding onde by hand calls the same function with its own buffer.
//!
//! Two placements:
//!
//! - **array** (default): the payload is a `static const unsigned char[]` in the generated file.
//!   Portable across every compiler and every cell, seals into the image (so signing just works),
//!   and costs about 6× the payload in C text.
//! - **section**: the payload is a separate file the linker places (`-sectcreate` on Mach-O, a
//!   generated `.incbin` on ELF). Smaller C text, faster compile; no COFF equivalent, so MSVC
//!   rejects the flag rather than silently downgrading.

use std::fmt::Write as _;

/// Where the payload lives.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Embed {
    /// A C array in the generated file.
    Array,
    /// A linker section (`.onde`), placed from a separate file.
    Section,
}

impl Embed {
    /// Parse `--embed`.
    pub fn parse(name: &str) -> Result<Embed, String> {
        match name {
            "array" => Ok(Embed::Array),
            "section" => Ok(Embed::Section),
            other => Err(format!(
                "unknown --embed {other:?}; expected array or section"
            )),
        }
    }
}

/// The Mach-O section the payload is placed in.
pub const MACHO_SEGMENT: &str = "__DATA";
/// The Mach-O section name.
pub const MACHO_SECTION: &str = "__onde";
/// The ELF section name.
pub const ELF_SECTION: &str = ".onde";

/// Generate the C file.
///
/// `payload` is only read for the array placement; the section placement writes the bytes to
/// `payload_path` and the C file only reads them back at run time.
pub fn c_file(
    embed: Embed,
    target: &crate::target::Target,
    version: &str,
    stamp: &str,
    payload: &[u8],
    payload_path: &str,
) -> Result<String, String> {
    let mut out = String::with_capacity(match embed {
        Embed::Array => 6 * payload.len() + 512,
        Embed::Section => 1024,
    });

    writeln!(
        out,
        "/* generated by ondec {version} for {target} — do not edit */"
    )
    .unwrap();
    writeln!(out, "/* engine: {stamp} */").unwrap();
    writeln!(out, "#include \"onde.h\"").unwrap();
    writeln!(out).unwrap();

    match embed {
        Embed::Array => {
            writeln!(out, "static const unsigned char onde_payload[] = {{").unwrap();
            for (index, byte) in payload.iter().enumerate() {
                if index % 16 == 0 {
                    out.push_str("    ");
                }
                write!(out, "0x{byte:02x},").unwrap();
                if index % 16 == 15 || index + 1 == payload.len() {
                    out.push('\n');
                } else {
                    out.push(' ');
                }
            }
            writeln!(out, "}};").unwrap();
            writeln!(out).unwrap();
            writeln!(out, "int main(int argc, char **argv) {{").unwrap();
            writeln!(
                out,
                "    return onde_main_payload(onde_payload, sizeof onde_payload, argc, argv);"
            )
            .unwrap();
            writeln!(out, "}}").unwrap();
        }
        Embed::Section if target.is_macho() => {
            writeln!(out, "#include <mach-o/getsect.h>").unwrap();
            writeln!(out, "#include <mach-o/ldsyms.h>").unwrap();
            writeln!(out).unwrap();
            writeln!(out, "int main(int argc, char **argv) {{").unwrap();
            writeln!(out, "    unsigned long size = 0;").unwrap();
            writeln!(
                out,
                "    const unsigned char *payload = (const unsigned char *)getsectiondata("
            )
            .unwrap();
            writeln!(
                out,
                "        (const struct mach_header_64 *)&_mh_execute_header, \"{MACHO_SEGMENT}\","
            )
            .unwrap();
            writeln!(out, "        \"{MACHO_SECTION}\", &size);").unwrap();
            writeln!(out, "    if (payload == NULL || size == 0) {{").unwrap();
            writeln!(
                out,
                "        /* The section the linker was told to create is missing: a build problem, \
                 not a user error. */"
            )
            .unwrap();
            writeln!(out, "        return 78;").unwrap();
            writeln!(out, "    }}").unwrap();
            writeln!(
                out,
                "    return onde_main_payload(payload, (size_t)size, argc, argv);"
            )
            .unwrap();
            writeln!(out, "}}").unwrap();
        }
        Embed::Section => {
            // ELF: the linker cannot `.incbin`, the assembler can. The generated `.S` defines
            // start/end symbols around the payload; this file references both, which is also what
            // keeps `--gc-sections` from discarding an otherwise unreferenced allocation section.
            writeln!(out, "extern const unsigned char onde_payload_start[];").unwrap();
            writeln!(out, "extern const unsigned char onde_payload_end[];").unwrap();
            writeln!(out).unwrap();
            writeln!(out, "int main(int argc, char **argv) {{").unwrap();
            writeln!(
                out,
                "    size_t size = (size_t)(onde_payload_end - onde_payload_start);"
            )
            .unwrap();
            writeln!(
                out,
                "    return onde_main_payload(onde_payload_start, size, argc, argv);"
            )
            .unwrap();
            writeln!(out, "}}").unwrap();
        }
    }

    let _ = payload_path;
    Ok(out)
}

/// The generated assembly for an ELF `--embed section` build.
///
/// `.incbin` takes a path the assembler opens; it is written absolute by the caller so the
/// assembler's working directory does not matter.
pub fn elf_payload_assembly(payload_path: &str) -> String {
    format!(
        "/* generated by ondec — do not edit */\n\
         \x20   .section {ELF_SECTION},\"a\",@progbits\n\
         \x20   .global onde_payload_start\n\
         \x20   .global onde_payload_end\n\
         \x20   .balign 16\n\
         onde_payload_start:\n\
         \x20   .incbin \"{payload_path}\"\n\
         onde_payload_end:\n\
         \x20   .section .note.GNU-stack,\"\",@progbits\n"
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::target::Target;

    fn darwin() -> Target {
        Target::parse("aarch64-apple-darwin").unwrap()
    }

    fn linux() -> Target {
        Target::parse("x86_64-unknown-linux-gnu").unwrap()
    }

    #[test]
    fn the_array_form_holds_every_byte_and_calls_the_entry_point() {
        let payload = [0x00u8, 0x7f, 0xff, 0x42];
        let text = c_file(
            Embed::Array,
            &darwin(),
            "0.1.0",
            "ONDE-ABI:1;stamp;",
            &payload,
            "app.bc",
        )
        .unwrap();

        assert!(text.contains("#include \"onde.h\""));
        assert!(text.contains("static const unsigned char onde_payload[] = {"));
        for byte in payload {
            assert!(text.contains(&format!("0x{byte:02x},")), "{text}");
        }
        assert!(text
            .contains("return onde_main_payload(onde_payload, sizeof onde_payload, argc, argv);"));
        assert!(text.contains("/* engine: ONDE-ABI:1;stamp; */"));
    }

    #[test]
    fn the_array_is_written_sixteen_bytes_to_a_line() {
        let payload: Vec<u8> = (0..40u8).collect();
        let text = c_file(Embed::Array, &darwin(), "0.1.0", "s", &payload, "x").unwrap();
        let body: Vec<&str> = text
            .lines()
            .skip_while(|line| !line.contains("onde_payload[] = {"))
            .skip(1)
            .take_while(|line| !line.starts_with("};"))
            .collect();
        assert_eq!(body.len(), 3, "40 bytes is 16 + 16 + 8: {body:?}");
        assert_eq!(body[0].matches("0x").count(), 16);
        assert_eq!(body[2].matches("0x").count(), 8);
    }

    #[test]
    fn the_macho_section_form_uses_getsectiondata() {
        let text = c_file(Embed::Section, &darwin(), "0.1.0", "s", &[], "app.bc").unwrap();
        assert!(text.contains("getsectiondata"));
        assert!(
            text.contains("mach_header_64"),
            "the 64-bit header is the one every v1 cell has: {text}"
        );
        assert!(text.contains("\"__DATA\""));
        assert!(text.contains("\"__onde\""));
        assert!(!text.contains("onde_payload[]"));
    }

    #[test]
    fn the_elf_section_form_references_start_and_end() {
        let text = c_file(Embed::Section, &linux(), "0.1.0", "s", &[], "app.bc").unwrap();
        assert!(text.contains("onde_payload_start"));
        assert!(text.contains("onde_payload_end"));

        let assembly = elf_payload_assembly("/tmp/ondec-build-x/app.bc");
        assert!(assembly.contains(".section .onde,\"a\",@progbits"));
        assert!(assembly.contains(".incbin \"/tmp/ondec-build-x/app.bc\""));
    }

    #[test]
    fn embed_parses_only_the_two_placements() {
        assert_eq!(Embed::parse("array"), Ok(Embed::Array));
        assert_eq!(Embed::parse("section"), Ok(Embed::Section));
        assert!(Embed::parse("append").is_err());
    }
}
